INSERT INTO `fanfics` VALUES (1,'Белый сниггерс в шоколадном глазе',10,'Жил был Андрей и была у него огромная шоколадная трещина. Андрей очень любил свою трещину. Как то раз Андрей шёл по летнему теплому лесу. Шел он долго, у него была жажда воды и тепла в своей любимой шоколадной трещине. Для него пословица гласящая :\"лучше жопа в тепле чем тепло в жопе\" Максимально не нравилась. Он \r\nВсегда мечтал чтобы в его шоколадную трещину залезло что то большое, жирное, маслянистое и тяжёлое. Андрей вышел на грунтовую дорогу. В лесу становилось всё больше сосновых деревьев. От жажды Андрею казалось что эти деревья так похожи на сниггерсы и что они просто идеально войдут в его шоколадную и неповторимую трещину. Долго ли шёл по лесу Андрей мы не знаем, ибо Андрей страдал неизлечимой болезнью рака жопы. Но несмотря на это его жопа имела гораздо больший интеллект чем голова. Вскоре Андрей наткнулся на дятла. На удивление дятел умел разговаривать. Дятел любезно позвал его к себе в дупло прекрасно зная что Андрей страдал синдромом Алисы в стране чудес (необходимо загуглить для понимания сюжета). Андрей из за синдрома подумал что он прекрасно залезет в дупло. На его удивление пролезла только голова. И тогда дятел принялся за работу. Андрей был не против. У дятла был огромный мускулистый и влажный сниггерс белого цвета. Дятел начал активно работать им с большой амплитудой. Андрей издавал звуки подобные женщине. Это был громкий и очень женственный \"Ах! \". Вскоре Андрей скончался. Мораль: выбирайте сниггерс себе по размеру','/static/images/placeholder.jpg',1,'2026-03-15 21:45:09'),(2,'Чай для двоих.. 💤',13,'МЫ РЕЗКО ОСУЖДАЕМ И НИ В КОЕМ СЛУЧАЕ НЕ ПОДДЕРЖИВАЕМ: НАЦИЗМ, ФАШИЗМ, РАСИЗМ, КСЕНОФОБИЮ, АНТИСЕМИТИЗМ, ИСЛАМОФОБИЮ, ГОМОФОБИЮ, ТРАНСФОБИЮ, СЕКСИЗМ, ЭЙДЖИЗМ, ДИСКРИМИНАЦИЮ ПО ИНВАЛИДНОСТИ, РЕЛИГИОЗНУЮ НЕТЕРПИМОСТЬ, ЭКСТРЕМИЗМ, ШОВИНИЗМ, ФИЗИЧЕСКОЕ И ПСИХОЛОГИЧЕСКОЕ НАСИЛИЕ, ДОМАШНЕЕ НАСИЛИЕ, ГЕНОЦИД, ТЕРРОРИЗМ, ПЫТКИ, ЖЕСТОКОЕ ОБРАЩЕНИЕ С ЖИВОТНЫМИ, КВАДРОБИНГ, ХОБИХОРСНИГ, ДЕТОУБИЙСТВО, СЕКСУАЛЬНОЕ НАСИЛИЕ, ТОРГОВЛЮ ЛЮДЬМИ, РАБСТВО, КИБЕРБУЛЛИНГ, ТРАВЛЮ (БУЛЛИНГ), СЕЛФХАРМ, ПРОПАГАНДУ СУИЦИДА, КОРРУПЦИЮ, ВАНДАЛИЗМ, ВЫМОГАТЕЛЬСТВО, МОШЕННИЧЕСТВО, КРАЖУ, ГРАБЕЖ, РАЗБОЙ, УБИЙСТВА, НАРКОТОРГОВЛЮ, НЕЗАКОННЫЙ ОБОРОТ ОРУЖИЯ, ПИРАТСТВО, ПРОПАГАНДУ ПРЕСТУПНОГО ОБРАЗА ЖИЗНИ, НАРКОМАНИЮ, АЛКОГОЛИЗМ, ТОКСИКОМАНИЮ, ИГРОВУЮ ЗАВИСИМОСТЬ, ДЕСТРУКТИВНЫЕ КУЛЬТЫ, ОПАСНЫЕ ЧЕЛЛЕНДЖИ, ФЕЙКОВЫЕ НОВОСТИ, ТЕОРИИ ЗАГОВОРА, ЛЖЕНАУКУ, МАНИПУЛЯЦИИ СОЗНАНИЕМ, ГАЗЛАЙТИНГ, ЭКОЛОГИЧЕСКИЙ ВАНДАЛИЗМ, ПРОПАГАНДУ ВОЙН, ВОЕННЫЕ ПРЕСТУПЛЕНИЯ, НАРУШЕНИЕ ПРИВАТНОСТИ, КЛЕВЕТУ, ХАРАССМЕНТ И ЛЮБЫЕ ДРУГИЕ ФОРМЫ НАСИЛИЯ, ДИСКРИМИНАЦИИ ИЛИ НЕЗАКОННОЙ ДЕЯТЕЛЬНОСТИ.\r\n\r\n                       ⚠️ здесь не будет никаких постельных сцен, поцелуев, и любых проявлений гейства со стороны персонажей, если вы пришли за этим, то разочарую, всё неправда, я не в коем случае не пытался никого оскорбить ⚠️\r\n\r\nЭто альтернативная вселенная фанфика *дружба это чудо*, где андрей не опоздал, а пришёл вовремя. \r\n\r\nchapter 1 /\r\n\r\n   Жил был Андрей, он был слегка туповат в жизни, но в программировании и технологии он был словно рыба в воде, тем самым утверждая своё превосходство над остальными. У него был друг, Семён, и они очень близко дружили...\r\n   Одним поздним вечером они как обычно решили поиграть в майнкрафт, и им было довольно таки безразлично то, что на следующее утро им прийдётся идти в школу. Как вдруг Семён внезапно пригласил Андрея в гости, потому что им было уже абсолютно всё равно на школу.\r\n\r\nС - может завтра ко мне вместо школы?\r\nА - нуу... вообще можно. Во сколько?\r\nс - кайф, жду в 4:30\r\nА - утра?\r\nС - да\r\n\r\n          *на минуту в звонке повисло молчание, но не успев оно стать неловким Андрей слегка рассмеявшись сказал*\r\n\r\nА - ты еблан? я не прийду к тебе в 4:30 утра, меня родители из дома не выпустят в такое время\r\nС - сбеги из дома, ты же квадробер\r\nА - во первых, я не квадробер, во вторых, как?\r\nС - из окна выпрыгни\r\nА - неее, я не смогу\r\nС - ладно... тогда во сколько ты сможешь?\r\nА - нуу.. давай в 8:40?\r\nС - окей, буду ждать\r\n\r\n          *вдруг в чате высвечивается надпись \"jimbo3383 was slain by villager\"*\r\n\r\nА - ...\r\nС - сочувствую\r\nА - почему когда я ударил голема на меня напал житель..я в алмазке А ОН СНЁС МЕНЯ С ОДНОГО УДАРА.. ЧЁ ЗА ХУЙН-\r\nС - это мод, я же говорил\r\nА - да у тебя этих модов больше 300\r\n  \r\n          *на следующее утро*\r\nАндрей постучал в дверь семена в 8:40\r\n\r\n          *дверь медленно открылась* \r\n\r\nА - пришел в 8:40, как договаривались.\r\nС - ты ахуел? я тебе адресс не говорил, не то что этаж и квартиру \r\nА - так я у Миши спросил          /* наглое враньё, кто то сталкер и инфо-цыган */\r\nС - ну проходи гном карманный\r\nА - ну спасибо пшеница ходячая          /* отдельная дань уважения оригинальному автору за столь изобретательные клички для этих двух недо-животных, я подумал это будет не красиво использовать вашу идею, так что я придумал свои. */\r\nС - предлагаю попить чай а потом пое-\r\nА - давай\r\nС - ?, чего перебиваешь, попить чай а потом поесть.\r\nА - а.. да, давай\r\nС - чего поник? \r\nА - всм\r\nС - ну ты низкий какой то\r\nА - . . . \r\nС - ладно ладно, только не кусайся.. /* намёк на чихуа-хуа */ ...тебе чай какой? или предпочтёшь кофе?\r\nА - мне кофе нельзя, давай чёрный чай просто, если есть то с лимоном\r\n\r\n          *и вот прошел час, они сидели на кухне и обсерали одноклассников, какие они низко интеллектуальные, как вдруг прозвучал звонок телефона что Семён оставил на зарядке в своей комнате* \r\n\r\nС - я сейчас *Семён резко встал и слегка быстрым шагом пошёл за телефоном*\r\nА - *вздох, и очередной глоток чая, терпкого, с мятной прохладой. Послевкусие вяжущее, и даже сахар не помог, два вкуса так и не слились, оставаясь чужими друг другу.* \r\n\r\n          *Андрей медленно встал из-за стола..*\r\n          *тем временем у Семёна*\r\n\r\nС - *очень бурный и интересный диалог который мне лень описывать и прописывать*.. давай, пока\r\n\r\n*попрощавшись с собеседником Семён положил телефон в карман и пошёл на кухню, где Андрей продолжал сидеть за столом и допивал чай*\r\n\r\nА - чего ты так долго?\r\nС - случайно, ладно, на чём мы остановились? \r\n\r\n          *Семён сел за стол, и отхлебнул пол кружки чая.. слегка уловив носом запах чая, пахший чем-то... непривычным. Не просто мятой или лимоном — в аромате чувствовалась странная не знакомая нотка, прикрытая сладковатым шлейфом корицы. Но, решив что ему кажется, он просто продолжил диалог со своим близким другом*\r\n\r\nА - ну а ты как сам вообще?\r\nС - я? хорошо, к чему такие вопросы?\r\nА - да просто..\r\n\r\n*Вдруг... что-то странное произошло. Семён не сразу понял что происходит, сначала лишь лёгкая слабость в коленях, будто после долгого бега. Потом пальцы перестали слушаться, и чашка с громким звоном упала на пол*\r\n\"Надо встать\", - мелькнула мысль, но тело не откликнулось. Он наблюдал, как его рука медленно сползает с колена, бессильно повисая в воздухе. Последнее, что он успел почувствовать - как спина бесшумно прилипла к спинке кухонного стула. И легкий, знакомый, но такой чужой смех человека, которого он считал своим другом*\r\n\r\nА - теперь ты мой..\r\n \r\n                                                              ...продолжение следует..\r\n\r\n\r\nпо вопросам писать сюда - https://t.me/anonaskbot?start=AnonymYagonQuestions','/static/images/placeholder.jpg',0,'2026-03-15 21:46:35'),(3,'Чай для двоих.. 💤 (2 часть)',13,'МЫ РЕЗКО ОСУЖДАЕМ И НИ В КОЕМ СЛУЧАЕ НЕ ПОДДЕРЖИВАЕМ: НАЦИЗМ, ФАШИЗМ, РАСИЗМ, КСЕНОФОБИЮ, АНТИСЕМИТИЗМ, ИСЛАМОФОБИЮ, ГОМОФОБИЮ, ТРАНСФОБИЮ, СЕКСИЗМ, ЭЙДЖИЗМ, ДИСКРИМИНАЦИЮ ПО ИНВАЛИДНОСТИ, РЕЛИГИОЗНУЮ НЕТЕРПИМОСТЬ, ЭКСТРЕМИЗМ, ШОВИНИЗМ, ФИЗИЧЕСКОЕ И ПСИХОЛОГИЧЕСКОЕ НАСИЛИЕ, ДОМАШНЕЕ НАСИЛИЕ, ГЕНОЦИД, ТЕРРОРИЗМ, ПЫТКИ, ЖЕСТОКОЕ ОБРАЩЕНИЕ С ЖИВОТНЫМИ, КВАДРОБИНГ, ХОБИХОРСНИГ, ДЕТОУБИЙСТВО, СЕКСУАЛЬНОЕ НАСИЛИЕ, ТОРГОВЛЮ ЛЮДЬМИ, РАБСТВО, КИБЕРБУЛЛИНГ, ТРАВЛЮ (БУЛЛИНГ), СЕЛФХАРМ, ПРОПАГАНДУ СУИЦИДА, КОРРУПЦИЮ, ВАНДАЛИЗМ, ВЫМОГАТЕЛЬСТВО, МОШЕННИЧЕСТВО, КРАЖУ, ГРАБЕЖ, РАЗБОЙ, УБИЙСТВА, НАРКОТОРГОВЛЮ, НЕЗАКОННЫЙ ОБОРОТ ОРУЖИЯ, ПИРАТСТВО, ПРОПАГАНДУ ПРЕСТУПНОГО ОБРАЗА ЖИЗНИ, НАРКОМАНИЮ, АЛКОГОЛИЗМ, ТОКСИКОМАНИЮ, ИГРОВУЮ ЗАВИСИМОСТЬ, ДЕСТРУКТИВНЫЕ КУЛЬТЫ, ОПАСНЫЕ ЧЕЛЛЕНДЖИ, ФЕЙКОВЫЕ НОВОСТИ, ТЕОРИИ ЗАГОВОРА, ЛЖЕНАУКУ, МАНИПУЛЯЦИИ СОЗНАНИЕМ, ГАЗЛАЙТИНГ, ЭКОЛОГИЧЕСКИЙ ВАНДАЛИЗМ, ПРОПАГАНДУ ВОЙН, ВОЕННЫЕ ПРЕСТУПЛЕНИЯ, НАРУШЕНИЕ ПРИВАТНОСТИ, КЛЕВЕТУ, ХАРАССМЕНТ И ЛЮБЫЕ ДРУГИЕ ФОРМЫ НАСИЛИЯ, ДИСКРИМИНАЦИИ ИЛИ НЕЗАКОННОЙ ДЕЯТЕЛЬНОСТИ.\r\n\r\n⚠️ здесь не будет никаких постельных сцен, поцелуев, и любых проявлений гейства со стороны персонажей, если вы пришли за этим, то разочарую, всё неправда, я не в коем случае не пытался никого оскорбить ⚠️\r\n\r\n϶ᴛо ᴀᴧьᴛᴇᴩнᴀᴛиʙнᴀя ʙᴄᴇᴧᴇннᴀя ɸᴀнɸиᴋᴀ *дᴩужбᴀ ϶ᴛо чудо*, ᴦдᴇ ᴀндᴩᴇй нᴇ оᴨоздᴀᴧ, ᴀ ᴨᴩиɯёᴧ ʙоʙᴩᴇʍя.\r\n\r\nchapter 2 /\r\n\r\n\r\nС - Мгх.. где я.. \r\n\r\n*очнуʙɯиᴄь ᴄᴇʍён оᴦᴧядᴇᴧᴄя, зᴀʍᴇᴛиʙ ноʙоᴇ оᴋᴩужᴇниᴇ. ᴛᴇʍный ᴨодʙᴀᴧ, ᴧиɯь нᴇбоᴧьɯᴀя ᴧᴀʍᴨочᴋᴀ ᴄʙᴇᴛиᴛ ᴄ ᴨоᴛоᴧᴋᴀ, ᴄᴧᴇᴦᴋᴀ ᴨᴩоᴧиʙᴀя ᴄʙᴇᴛ ʙ ϶ᴛо ᴛёʍноᴇ ᴨоʍᴇщᴇниᴇ. \r\nᴦоᴧоʙᴀ ужᴀᴄно боᴧᴇᴧᴀ.. ʙдᴩуᴦ, он уᴄᴧыɯᴀᴧ ᴄᴛᴩᴀнный ɯоᴩох.. ʍᴇдᴧᴇнно ᴨоʙᴇᴩнуʙ ᴦоᴧоʙу ʙ нᴀᴨᴩᴀʙᴧᴇниᴇ зʙуᴋᴀ он зᴀʍᴇᴛиᴧ ᴋᴀᴋ ᴋᴛо ᴛо, ᴄᴛоя ᴋ нᴇʍу ᴄᴨиной, чᴛо ᴛо дᴇᴧᴀᴧ.. \r\nКАК ВДРУГ\r\n϶ᴛоᴛ чᴇᴧоʙᴇᴋ ᴩᴀзʙᴇᴩнуᴧᴄя, ᴨоᴛянуʙɯиᴄь зᴀ чᴇʍ ᴛо ᴄᴛоящиʍ ᴩядоʍ нᴀ ᴄᴛоᴧᴇ, ᴛᴇʍ ᴄᴀʍыʍ ᴨоʙᴇᴩнуʙɯиᴄь ᴨᴩᴀᴋᴛичᴇᴄᴋи ʙ ᴄᴛоᴩону ᴛоᴧьᴋо чᴛо очнуʙɯᴇᴦоᴄя ʍᴀᴧьчиɯᴋи.*\r\n\r\nС - Паша?.. \r\n\r\n*ᴄ удиʙᴧᴇниᴇʍ ᴄᴨᴩоᴄиᴧ ᴄᴇʍён, зᴀʍᴇᴛиʙ знᴀᴋоʍоᴦо чᴇᴧоʙᴇᴋᴀ ʙ ᴋᴀзᴀᴧоᴄь бы ᴛᴀᴋоʍ ᴄᴛᴩᴀнноʍ ʍᴇᴄᴛᴇ.*\r\n\r\nП - Оо, проснулся. С добрым утром\r\nС - Всмысле.. какое утро.. где мы вообще.. \r\nП - В подвале\r\nС - А я думал в школе проснулся\r\nП - У Андрея в подвале. Этот маленький пидор меня сюда заманил и теперь заставляет дронов ему делать.\r\nС - А в чём проблема просто его отпиздить?\r\nП - Да я бы с радостью, но ему Ярик и Гриша помогают.\r\nС - Гриша?\r\nП - Ну Гоша\r\n\r\nнᴀ ʍинуᴛу ᴨоʙиᴄᴧо нᴇбоᴧьɯоᴇ ʍоᴧчᴀниᴇ, будᴛо ᴋоʍᴨьюᴛᴇᴩ ᴨыᴛᴀᴇᴛᴄя ᴄоʙᴇᴩɯиᴛь ᴨоиᴄᴋоʙой зᴀᴨᴩоᴄ\r\n\r\nС - Мда, а хули они ему помогают вообще?\r\nП - Я ебу? наверно он им платит\r\nС - Деньгами типо?\r\nП - Типо отсосами\r\nС - Ясно понятно\r\n\r\n*ʙдᴩуᴦ дʙᴇᴩь ᴨодʙᴀᴧᴀ оᴛᴋᴩыʙᴀᴇᴛᴄя, зᴀходиᴛ яᴩиᴋ, ᴀ ᴄᴧᴇдоʍ ᴀндᴩᴇй*\r\n\r\nА - Как идёт прогресс Паша? О, с добрым утром Семён, не переживай, тебе мы тоже дело найдём.\r\nЯ - *ʍоᴧчᴀᴧиʙо нᴀбᴧюдᴀᴇᴛ, ᴄ ᴀᴦᴩᴇᴄᴄиʙно-бᴇз ϶ʍоционᴀᴧьныʍ ᴨоᴋᴇᴩɸᴇйᴄоʍ*\r\nП - Да пошёл ты на-\r\nС - Андрей, чё за хуйня \r\n\r\n*бᴇз цᴇᴩᴇʍонно ᴨᴇᴩᴇбиʙᴀᴇᴛ ᴄᴇʍён ᴨᴀɯу*\r\n\r\nА - М? Что конкретно тебе не нравится? \r\n\r\n*ᴄᴨᴩоᴄиᴧ ᴀндᴩᴇй, ᴨоᴨиʙᴀя ᴄʙой чёᴩный чᴀй ᴄ ᴋоᴩицᴇй*\r\n\r\nС - Чё я сделать успел, ладно Паша, С ним всё понятно - ахуевший.\r\nА - Ты мне лимон в чай не положил\r\nС - . . . \r\nЯ - Ебать ты монстр пшеничный конечно \r\nП - Не ну это перебор Сём.. Так даже я бы не поступил\r\nС - Да что за буллинг начался..\r\nА - Ладно проехали, Ярик, я за лимоном и чаем, ты за главного\r\nП - А мож-..\r\nА - Тебе ничего не буду покупать, работай давай.\r\n\r\n*ᴋᴀᴋ обычно ᴨᴇᴩᴇбиᴧи бᴇдноᴦо ᴨᴀʙᴧᴀ*\r\n\r\nЯ - Можно их пиздить если буянить будут?\r\nА - Да.\r\nС - Нет\r\nА - Не тебя спрашивали, иди паше помогай\r\n\r\n*ᴄᴋиᴨ, ᴀндᴩᴇй уɯёᴧ, оᴄᴛᴀʙиʙ яᴩоᴦо ᴨоᴧу-ᴨоᴋᴇᴩᴀ зᴀ ᴦᴧᴀʙноᴦо, ᴨᴀɯᴀ ᴛᴇʍ ʙᴩᴇʍᴇнᴇʍ ᴄᴇᴧ зᴀ дᴩон, ᴄ ᴛᴀᴋиʍ ʙидоʍ будᴛо чᴛо ᴛо дᴇᴧᴀᴇᴛ очᴇнь ʙᴀжноᴇ, ʙᴄᴋоᴩᴇ ᴄᴇʍён ᴨодоɯᴇᴧ*\r\n\r\nС - Паш.. \r\n\r\n*ᴨоᴧу ɯёᴨоᴛоʍ ᴄᴋᴀзᴀᴧ ᴄᴇʍён*\r\n\r\nС - Давай пока Андрея нет просто разберёмся с этим.. \r\n\r\n*ᴋиʙнуʙ ʙ ᴄᴛоᴩону яᴩиᴋᴀ, ᴄᴛояʙɯᴇᴦо у дʙᴇᴩи, ᴄᴋᴀзᴀᴧ ᴄᴇʍён*\r\n\r\nП - Хм.. Хорошая идея.. Нападём в открытую или один отвлечёт?\r\nС - Да давай напролом просто\r\nЯ - Эй, вы там чё перешёптываетесь?\r\nП - Не твоё дело\r\nЯ - Я щас за такое кому то по ебалу то стукну\r\nП - А ты попробуй\r\n\r\n...продолжение следует..\r\n\r\nпо вопросам писать сюда - https://t.me/anonaskbot?start=AnonymYagonQuestions\r\nпредлагайте ваши шипы для будующих фанфиков пожалуйста 🙏','/static/images/placeholder.jpg',0,'2026-03-15 21:47:19'),(4,'Чай для двоих.. 💤 (3 часть)',13,'МЫ РЕЗКО ОСУЖДАЕМ И НИ В КОЕМ СЛУЧАЕ НЕ ПОДДЕРЖИВАЕМ: НАЦИЗМ, ФАШИЗМ, РАСИЗМ, КСЕНОФОБИЮ, АНТИСЕМИТИЗМ, ИСЛАМОФОБИЮ, ГОМОФОБИЮ, ТРАНСФОБИЮ, СЕКСИЗМ, ЭЙДЖИЗМ, ДИСКРИМИНАЦИЮ ПО ИНВАЛИДНОСТИ, РЕЛИГИОЗНУЮ НЕТЕРПИМОСТЬ, ЭКСТРЕМИЗМ, ШОВИНИЗМ, ФИЗИЧЕСКОЕ И ПСИХОЛОГИЧЕСКОЕ НАСИЛИЕ, ДОМАШНЕЕ НАСИЛИЕ, ГЕНОЦИД, ТЕРРОРИЗМ, ПЫТКИ, ЖЕСТОКОЕ ОБРАЩЕНИЕ С ЖИВОТНЫМИ, КВАДРОБИНГ, ХОБИХОРСНИГ, ДЕТОУБИЙСТВО, СЕКСУАЛЬНОЕ НАСИЛИЕ, ТОРГОВЛЮ ЛЮДЬМИ, РАБСТВО, КИБЕРБУЛЛИНГ, ТРАВЛЮ (БУЛЛИНГ), СЕЛФХАРМ, ПРОПАГАНДУ СУИЦИДА, КОРРУПЦИЮ, ВАНДАЛИЗМ, ВЫМОГАТЕЛЬСТВО, МОШЕННИЧЕСТВО, КРАЖУ, ГРАБЕЖ, РАЗБОЙ, УБИЙСТВА, НАРКОТОРГОВЛЮ, НЕЗАКОННЫЙ ОБОРОТ ОРУЖИЯ, ПИРАТСТВО, ПРОПАГАНДУ ПРЕСТУПНОГО ОБРАЗА ЖИЗНИ, НАРКОМАНИЮ, АЛКОГОЛИЗМ, ТОКСИКОМАНИЮ, ИГРОВУЮ ЗАВИСИМОСТЬ, ДЕСТРУКТИВНЫЕ КУЛЬТЫ, ОПАСНЫЕ ЧЕЛЛЕНДЖИ, ФЕЙКОВЫЕ НОВОСТИ, ТЕОРИИ ЗАГОВОРА, ЛЖЕНАУКУ, МАНИПУЛЯЦИИ СОЗНАНИЕМ, ГАЗЛАЙТИНГ, ЭКОЛОГИЧЕСКИЙ ВАНДАЛИЗМ, ПРОПАГАНДУ ВОЙН, ВОЕННЫЕ ПРЕСТУПЛЕНИЯ, НАРУШЕНИЕ ПРИВАТНОСТИ, КЛЕВЕТУ, ХАРАССМЕНТ И ЛЮБЫЕ ДРУГИЕ ФОРМЫ НАСИЛИЯ, ДИСКРИМИНАЦИИ ИЛИ НЕЗАКОННОЙ ДЕЯТЕЛЬНОСТИ.\r\n⚠️ здесь не будет никаких постельных сцен, если вы пришли за этим, то разочарую, всё неправда, я не в коем случае не пытался никого оскорбить ⚠️\r\n\r\n                   ⚠️   БУДЕТ ПОЦЕЛУЙ, ГЕЙСТВ НЕ БУДЕТ, ТОЛЬКО КРЕПКАЯ МУЖСКАЯ ДРУЖБА  ⚠️\r\n\r\n϶ᴛо ᴀᴧьᴛᴇᴩнᴀᴛиʙнᴀя ʙᴄᴇᴧᴇннᴀя ɸᴀнɸиᴋᴀ *дᴩужбᴀ ϶ᴛо чудо*, ᴦдᴇ ᴀндᴩᴇй нᴇ оᴨоздᴀᴧ, ᴀ ᴨᴩиɯёᴧ ʙоʙᴩᴇʍя.\r\nchapter 3 /\r\n\r\n*ʙᴄᴨоʍниʍ чᴛо быᴧо*\r\n\r\nЯ - Эй, вы там чё перешёптываетесь?\r\nП - Не твоё дело\r\nЯ - Я щас за такое кому то по ебалу то стукну\r\nП - А ты попробуй\r\n\r\n...продолжение следует..\r\n\r\n*яᴩоᴄᴧᴀʙ ужᴇ ᴨодняᴧ ᴋуᴧᴀᴋ ʙʙᴇᴩх, зᴀʍᴀхиʙᴀяᴄь, чᴛобы удᴀᴩиᴛь ᴨᴀɯу, но, нᴀ ᴇᴦо удиʙᴧᴇниᴇ, ᴛоᴛ ᴩᴇзᴋо ᴨᴇᴩᴇхʙᴀᴛыʙᴀᴇᴛ ᴇᴦо ᴋуᴧᴀᴋ и ᴛянᴇᴛ ᴋ ᴄᴇбᴇ, нᴇ ᴩᴀᴄᴄчиᴛᴀʙ, чᴛо яᴩиᴋ дᴩыщ. ʙ иᴛоᴦᴇ ᴨоᴧучиᴧоᴄь ᴛᴀᴋ, чᴛо ᴨᴀʙᴇᴧ ᴨᴩиᴛянуᴧ ᴇᴦо ᴄᴧиɯᴋоʍ ᴄиᴧьно, из-зᴀ чᴇᴦо их ᴦубы ᴄᴧучᴀйныʍ обᴩᴀзоʍ ᴄоʍᴋнуᴧиᴄь ʙʍᴇᴄᴛᴇ, ᴛо ᴇᴄᴛь они ᴨоцᴇᴧоʙᴀᴧиᴄь.\r\nхоᴛь ϶ᴛо и ᴨᴩоизоɯᴧо ʙ ʍᴦноʙᴇниᴇ, яᴩоᴄᴧᴀʙу ϶ᴛоᴦо быᴧо доᴄᴛᴀᴛочно, чᴛобы ʙыᴩубиᴛьᴄя. ᴨоᴄᴧᴇ чᴇᴦо ᴨᴀʙᴇᴧ ᴨᴩоᴄᴛо ᴄᴛояᴧ ʙ ᴄᴛуᴨоᴩᴇ, нᴇ ᴨониʍᴀя, чᴛо ᴛоᴧьᴋо чᴛо ᴨᴩоизоɯᴧо.*\r\n\r\nС - Так ты гей всё таки? \r\n\r\n*нᴇ дᴀʙ обᴩᴀзоʙᴀᴛьᴄя нᴇᴧоʙᴋоʍу ʍоᴧчᴀнию ᴄᴋᴀзᴀᴧ ᴄᴇʍён*\r\n\r\nП - Нет *ᴦᴩубо оᴛʙᴇᴛиᴧ ᴨᴀɯᴀ, ᴨоᴄᴧᴇ чᴇᴦо ᴛихо добᴀʙиᴧ* себе подобных ищешь?..\r\nС - Что?\r\nП - Ничего?\r\n\r\n* . . . *\r\n\r\nС - Ладно, что делать будем?\r\nП - Давай заберём его с собой и перевоспитаем?\r\nС - Давай, звучит как хорошая идея\r\n\r\n*ᴨᴀɯᴀ ʙзяᴧ яᴩиᴋᴀ зᴀ ноᴦу и ᴨоᴛᴀщиᴧ ʙʙᴇᴩх ᴨо ᴧᴇᴄᴛницᴇ*\r\n\r\nС - Меня подожди! \r\n\r\n*ᴄᴋᴀзᴀᴧ ᴄᴇʍён ᴨоᴄᴨᴇʙᴀя зᴀ ниʍ*\r\n*ʙыйдя из ᴨодʙᴀᴧᴀ они обнᴀᴩужиᴧи чᴛо нᴀходяᴛᴄя ʙ ᴋᴀᴋоʍ ᴛо оᴦᴩоʍноʍ доʍᴇ, ʙидиʍо ᴀндᴩᴇя?*\r\n\r\nП - Надо бы выход найти\r\nС - Да ты капитан очевидность я смотрю?\r\nП - А что, завидуешь?\r\n\r\n*ʙдᴩуᴦ, их ᴩᴀзᴦоᴩᴀющийᴄя ᴋᴀᴋ ʍᴀᴧᴇньᴋих ᴋоᴄᴛёᴩ, ᴧᴇᴦᴋий ᴄᴨоᴩ быᴧ ᴨᴩᴇᴩʙᴀн ᴄᴛᴩᴀнныʍ зʙуᴋоʍ.. хᴩᴀᴀᴨ??*\r\n\r\nП - Тшш..!\r\n\r\n*ɯиᴋнуᴧ ᴨᴀɯᴀ, и ʍᴀхнуᴧ ᴩуᴋой ᴛиᴨо ᴨоᴋᴀзыʙᴀя \"ᴨоɯᴧи\"*\r\n*они ᴨодᴋᴩᴀᴧиᴄь ᴋ ʍᴇᴄᴛу оᴛᴋудᴀ иᴄходиᴧ ϶ᴛоᴛ хᴩᴀᴨ, ϶ᴛо быᴧᴀ ᴨᴩихожᴀя, у ʙходной дʙᴇᴩи нᴀ ᴨоᴧу ᴄᴨᴀᴧ ᴦᴩи-.. ᴛоᴇᴄᴛь.. ᴦоɯᴀ?*\r\n*ᴄᴇʍён ᴄ ᴧёᴦᴋиʍ удиʙᴧᴇниᴇʍ ᴨоᴄʍоᴛᴩᴇᴧ нᴀ ᴨᴀɯу, ᴋоᴛоᴩоᴦо, ʙидиʍо ϶ᴛᴀ ᴋᴀᴩᴛинᴀ и нᴇ ᴄʍущᴀᴧᴀ ʙоʙᴄᴇ, будᴛо ᴋᴀждый дᴇнь ᴛᴀᴋоᴇ ʙидᴇᴧ*\r\n\r\nП - Поверь, это вполне нормально Сём *ɯёᴨоᴛоʍ ᴄᴋᴀзᴀᴧ ᴨᴀɯᴀ*\r\nС - А где Ярик? *ᴛᴀᴋиʍ жᴇ ɯёᴨоᴛоʍ оᴛʙᴇᴛиᴧ ᴄᴇʍён*\r\nП - Всмысле, у тебя был? *ужᴇ чуᴛь ᴦᴩоʍчᴇ ᴨᴩоɯᴇᴨᴛᴀᴧ ᴨᴀɯᴀ*\r\nС - Как у меня? ты же его нёс! ну тащил.. *оᴛʙᴇчᴀᴧ ᴇʍу ᴄᴇʍён*, ничего тебе уже доверить нельзя, идиот \r\n\r\n*ᴨᴀɯᴀ ужᴇ хоᴛᴇᴧ оᴛʙᴇᴛиᴛь, ᴋᴀᴋ ᴦоɯᴀ ᴨоʙᴇᴩнуᴧᴄя нᴀ дᴩуᴦой боᴋ, чᴛо ᴛо ʙоᴩчᴀ ᴨод ноᴄ.. ᴨоᴄᴧᴇ чᴇᴦо ʍᴀᴧьчиᴋи бᴇз ᴄᴧоʙ ᴨоняᴧи чᴛо ᴋонɸᴧиᴋᴛы иʍ ᴛуᴛ нᴇ ᴨоʍоᴦу*\r\n*ʙᴇᴩнуʙɯиᴄь обᴩᴀᴛно ʙ ϶ᴛоᴛ ᴩᴀз ᴄᴇʍён ᴨоᴨыᴛᴀᴧᴄя ᴨодняᴛь яᴩиᴋᴀ нᴀ ᴩуᴋи, но ᴇᴦо ᴨᴇᴩᴇхʙᴀᴛиᴧ ᴨᴀɯᴀ*\r\n\r\nП - Давай уж я сам, я друга пидору не отдам \r\nС - Да ты заебал, ты больше на гея смахиваешь вообще-то, кого не спроси все так ответят\r\nП - Так, всё, пошли уже, если Гоша проснётся нам пизда, я не хочу обратно в подвал, ну и ты тоже не хочешь вроде\r\nС - Через главную дверь не выйдем, пошли искать заднюю дверь если она есть.. если что в окно прыгнем, я тебя подтолкну\r\nП - Женщины вперёд\r\nС - Я знаю, по-этому и предлагаю тебе первым\r\n\r\n*дᴀжᴇ учиᴛыʙᴀя ʙ ᴋᴀᴋой они обᴄᴛᴀноʙᴋᴇ, они ʙᴄё ᴩᴀʙно уʍудᴩяᴧиᴄь нᴀходиᴛь ʙᴩᴇʍя дᴧя ɯуᴛоᴋ и ᴨодᴋоᴧоʙ, ᴧᴇᴦᴋо ᴄʍᴇяᴄь нᴀд ɸᴩᴀзᴀʍи чᴛо ᴨᴩоʍᴇᴧьᴋᴀᴧи ʙ их диᴀᴧоᴦᴀх*\r\n\r\nНо мы забыли.. забыли об Андрее! что же там у него?..\r\n\r\n*ʙ ʍᴀᴦᴀзинᴇ*\r\n\r\nАндрей шёл к кассе с небольшой корзинкой, в которой лежали: корица, мандарины, лимоны, печенье «Нелюбятово» и «Неюбилейное»\r\n\r\nА - Ухх.. *ᴄᴧᴇᴦᴋᴀ уᴄᴛᴀᴧый, ᴀндᴩᴇй ʙыᴦᴩужᴀᴧ ᴛоʙᴀᴩы из ᴋоᴩзинᴋи нᴀ ᴧᴇнᴛу, нᴇ ᴄʍоᴛᴩя нᴀ ᴋᴀᴄᴄиᴩᴀ*\r\n\r\n*ᴋᴀᴄᴄиᴩ ᴨᴩобиᴧ ʙᴄᴇ ᴛоʙᴀᴩы, и ʙдᴩуᴦ ᴨᴩозʙучᴀᴧ знᴀᴋоʍый ᴦоᴧоᴄ..*\r\n\r\nМ - Пакетик брать будите? *ᴄᴋᴀзᴀᴧ ʍихᴀиᴧ ᴄ ᴧёᴦᴋой уᴄʍᴇɯᴋой ʙ ᴦоᴧоᴄᴇ*\r\nА - А.. ну.. да.. Миша а ты чего тут... откуда вообще.. 👉👈\r\nМ - Я у них сок яблочный пиздил, а они меня поймали, вот отрабатываю теперь \r\nА - А.. сочувствую.. а сколько ты спиздил?\r\nМ - Нууу.. коробок 100 Садов Придонья, 80 Любимый, 20 Мой, и 28 Доброго\r\n\r\n*ᴀндᴩᴇй ᴄ нᴇбоᴧьɯиʍ (ᴋᴀᴋ ᴇᴦо ᴩоᴄᴛ) удиʙᴧᴇниᴇʍ ᴨоᴄʍоᴛᴩᴇᴧ нᴀ ʍиɯу, ᴋоᴛоᴩый быᴧ ʙ дʙᴀ ᴩᴀзᴀ ʙыɯᴇ ᴇᴦо*\r\n\r\nМ - А что?\r\nА - Нет.. ничего.. я картой оплачу..\r\n\r\n...продолжение следует..\r\nпо вопросам писать сюда - https://t.me/anonaskbot?start=AnonymYagonQuestions\r\nпредлагайте ваши шипы для будующих фанфиков пожалуйста 🙏','/static/images/placeholder.jpg',0,'2026-03-15 21:47:49'),(5,'любитель дронов',10,'жил был некий Паша который очень сильно любил дроны, и после его 8 летия когда его облапали негры в его племени, это кстати объясняет почему он черны, он нашёл удивительные детали под деревом и тогда он впервые собрал дрон. однажды во время полётов дрон залетел в его маленькую черную попку ему понравилось и он начал заниматься этим каждый день. с каждым днем его попка расширялась и расширялась. к его 15 летию его очко стало размером с черную дыру. оно даже было больше шоколадной трещины Андрея. от него осталось только чёрная дыра и его маленькая усатая головка. когда паша  по улице его чёрная дыра поглощала все живое. одним солнечным днем Паша шёл по улице и вдруг сзади него раздается сверхзвуковой хлопок. это был его любимый турбоджет . турбоджет отклонился от курса из за гравитационной аномалии пашиной жопы. Белый турбоджет на всей скорости влетел в черную дыру. последнее что мы слышали это машины крики и звуки увеличения мощности чёрной дыры','/static/images/placeholder.jpg',1,'2026-03-15 21:50:21'),(6,'Любитель дронов часть 2',10,'Итак.произошел атомный взрыв. Пашино очко скалапсировало в мультивселенную. Пашино здоровье сильно пострадало. Он ели полз. Он звал о помощи, его очко засасывало его, а турбоджет очутился в другой вселенной. В очке паши ещё давно были кротовые норы, но теперь они сжимают пространство и время. Прошлые кротовые норы в очке паши ему мешали, из за них его очко было уже. Паша всегда мечтал об огромной жопе, но он даже не догадывался что она станет настолько большая. Паша долго полз с мультивселенной в жопе. Как вдруг он встретил андрея, и у них началась не равная битва трещин. В конце концов паша выиграл и засосал шоколадную трещину Андрея. Андрей к его огромному сожалению потерял его любимую шоколадную трещину (Пояснение почему Андрей жив: так как у пали взорвалось очко он сам не заметил как попал в мультивселенную где Андрей был жив) . В процессе битвы Пашино очко тоже порвалось. Паша скончался\r\nP.S. хеппи энд паша умер а Андрей остался жив и лишился такой тяжёлой трещины. Также хочу написать что Пашина жопа всегда была жирной и чёрной но это мешало бы сюжету','/static/images/placeholder.jpg',1,'2026-03-15 21:50:55'),(7,'ДРУЖБА ЭТО ЧУДО (часть  1)',17,'жил был андрей он был дебилом в жизни но по технологии вертел всех на хую. у него был друг семен и они очень ДРУЖИЛИ. одним вечером они решили поиграть в майн поздно вечером и им было пох что завтра в школу надо жопу тащить. \r\nкак вдруг семен пригласил андрея в гости потому что на хую они вертели эту школу. \r\n\r\nс- может завтра ко мне вместо школы?\r\nа - гогогого\r\nс - дадададад жду в 4:30 утра\r\n\r\nна след утро\r\n\r\nандрей постучал в дверь семена в 16:30 \r\n\r\nс - да ты шалуха сыктывкарская какого х ты опоздал?\r\nа - пришел в 16:30 как договаривались\r\n\r\nсемен был недоволен потому что он ждал его целый день, столько времени в пустую а могли бы пое...\r\n\r\nс - ну проходи чак-чак длиноволосый \r\nа - ну спасибо халва белобрысая\r\n\r\nони прошли пить чай и семен решил за непослушание чак-чака подсыпать ему в чай возбудитель (потому что нехуй)\r\nи вот прошел часик они сидели на кухне и обсирали одноклассников какие они дауны\r\n\r\nвдруг андрею че то поплохело, дыхание участилось лицо покраснело а вниз начало неприятно скручивать\r\n\r\nс - чел че с тобой на помидор похож\r\nа - да я наверно в туалет схожу....\r\n\r\nандрей медленно встал из зо стола и еле как доковылял до ванной. медленно открыл дверь, зашел в комнату и оперся руками на раковину. \r\n\r\nа - че за нахуй?\r\n\r\nон ополоснул свое лицо холодной водой и вышел из ванной надеясь что ему со временем полегчает. семен посмотрел на него нечитаемым взглядом и андрей присев за стол не понял что он означает, одурманенный разум андрея начал подкидывать разные фантазии и рисовать в голове странные и непристойные картины которые он не мог выкинуть из головы смотря на своего *друга*. \r\n\r\nс - тебе помочь?...)','/static/images/placeholder.jpg',0,'2026-03-15 21:52:20'),(8,'ДРУЖБА ЭТО ЧУДО (ФИНАЛ)',17,'сами додумайте че там произошло тут не извращенцы сидят \r\n👌👈👌👈 - НЕ НАМЁК (ягон спс за пиар)','/static/images/placeholder.jpg',0,'2026-03-15 21:53:23'),(9,'Очередная смерть анусного суриката',10,'Жил был паша чмырь-богатырь\r\nего кастрировали когда ему было 3.\r\nОт этого он мутировал в человека дрона.\r\nИ любил он домогаться до женщин помладше,\r\nно они ему никогда не нравились\r\nон просто пытался доказать что он не гей.\r\nКогда паша видел женщин новорожденных он спрыгивал с ветки и летел к ней.\r\nОбнимал он женщин красных ибо хотел он доказать что не либераха нетрадиционный.\r\nНе нравился этот субостат триклятый народу.\r\n\r\nНарод долго терпел\r\nибо на чурку похож да геем казался.\r\nКак то раз сидя на ветке наш богатырь чмыревый повидал диво дивное,\r\nорава узбеков шла с арбузами мимо него.\r\nУ нашего героя потекли слюньки.\r\nОн стремительно полетел с ветки к ним,\r\nвы как нормальные читатели подумали что он захотел арбузика.\r\nНо вероятно вы забыли что паша гей,\r\nи вот летит паша на всей скорости к этим узбекам.\r\nОдин из узбеков достаёт член\r\nИ паша на всей скорости врезается и насаживается глоткой на член.\r\nИ наш герой застрял на члене\r\nСзади подходит орава узбеков и начинает жеска насиловать пашу арбузом.\r\nПаша кричал, захлебывался от боли,\r\nно ему нравилось.\r\nПаша кричал:\r\n\"Ещё! Ещё!\".\r\nУзбеки не сдавались\r\nи жеска страпонили пашу.\r\nКак вдруг\r\nОдин из узбеков достал плетку\r\nи тут понеслось\r\nчерез время орава узбеков достала фонарный столб.\r\nДолго ли коротко насиловали пашу фонарный столбом нам неизвестно.\r\nМимо проходила кампания парней.\r\nТолпа людей начала жескую битву (чтобы пашу запинать ибо был он геем-педофилом).\r\nУзбеки долго удерживали оборону,\r\nно в конце концов узбеки отбили пашу от рук пацанов.\r\n\r\nИ унесли раненого объекта для насилования в подвал.\r\nПашу снова начали насиловать но уже в стиле бдсм.\r\nПацаны нашли пашу и узбеки начали убегать с пашей на руках.\r\nНо пацаны догоняли\r\nВскоре узбеки вызвали подмогу и через доли секунды примчал истребитель курьер и раскидал толпу пацанов\r\nНо курьер не работает бесплатно.\r\nОн достал свой гигантский мусскулистый член и начал обмазывать его по губам паши.\r\nУзбек начал жеска пехать его в его жирную жопу.\r\nВскоре паша вновь скончался\r\nИ его нашли и избили пацаны.','/static/images/placeholder.jpg',1,'2026-03-15 21:53:57'),(10,'Шёпот',15,'Ночь. Время близится к полуночи. Юный маг, периодически запинаясь, пытается призвать демона. После произношения заклинания ничего не изменилось, лишь пламя свечей слегка шелохнулось.\r\n\r\n— Да твою мать, почему ничего не получается?! — матерясь, выговаривает он и начинает с начала.\r\nЗа этой картиной из ада через зеркало наблюдает сам демон.\r\n\r\n— Хахаха, ну что за идиот, даже заклинание по книжке прочитать не может, я уже не говорю про неправильно нарисованную пентограмму, — смеясь, проговаривает он.\r\n\r\nЗаметив эту картину, к нему подтянулись ещё несколько демонов, и уже они впятером смеялись над парнем.\r\n\r\nВ это время во дворец возвращался сам Сатана. Он был на переговорах с архангелами, и эти пернатые существа не на шутку выбесили его. Заметив компанию возле колонны, которая по сути должна была охранять ворота, он стоял там и с чего-то бурно смеялся. И так, злой Сатана двинулся на них.\r\n\r\n— Вы чего тут устроили?! Вам что, работы мало, что вы успеваете найти время на шутки? Сейчас отправлю вас котлы чистить, чтоб неповадно было!\r\n\r\n— Ой, мой лорд, — проговорил один из них испуганным голосом.\r\n\r\n— Мой лорд, тут просто ситуация такая смешная. Нежелаете посмотреть? — пролепетал другой, протягивая ему зеркало.\r\n\r\n— Не хочу ничего слышать. Марш за работу, бестолочи! — грозно проговорил Сатана, забрав у них стекляшку.\r\n\r\nДемоны тут же бросились в расыпную, лишь бы не охватить от него. Сам Сатана направился в тронный зал.\r\n\r\nСидя там, он устало потер нос, когда услышал какие-то звуки. Они доносились из того самого зеркала, лежащего на небольшом столике рядом с троном.\r\n\r\nЗаглянув в него, он увидел парня, который по видимому совершал какой-то ритуал. Мальчишка топал ногами и проклинал весь свет. Это показалось Высшему милым и забавным. Он, став невидимым, перенёсся на Землю.\r\n\r\n— Да почему у меня не получается? Что я делаю не так?! — гневно выговаривает маг, садясь на диван, попутно кинув книгу \"Помощь начинающим экзорцистам\" на пол.\r\n\r\nТакая реакция позабавила демона, и он, осмотревшись, со смешком заметил, что у парня в первую очередь неправильно нарисована пентограма.\r\n\r\nПодлетев к книге, он раскрыл её на нужной странице. Маг заметил шевеление страниц. Сначала он испугался, но потом списал это на ветер из открытого окна. Подняв книгу, он увидел свою ошибку и начал поправлять символы на пентограмме, не заметив, что пару было либо исправлено, либо дорисовано Сатаной.\r\n\r\nЗакончив, парень решил попробовать ещё раз, но снова ничего. Да, эффект был получше, но до результата как до Китая.\r\n\r\nОтчаявшись, маг хотел было уже всё бросить и пойти спать, но тут услышал голос. Он был тихий, но такой приятный.\r\n\r\n— Произноси слова более уверенно и не запинайся. Давай же, я помогу, — прошептал голос прямо над ухом, от чего у мага по спине побежали мурашки. Сначала он испугался, но голос звучал так уверенно, а в душе возникло странное спокойствие.\r\n\r\nПоддавшись ему, парень начал повторять за голосом. Как только последнее слово слетело с языка, мгновение — и из круга поднялся силуэт, обволакиваемый красным пламенем и тёмной дымкой. Сатана появился — великий и могущественный, но с хитрой улыбкой на губах.\r\n\r\n— Ну здравствуй, смертный, как же долго ты меня вызывал, что аж помогать пришлось, — проговорил он.\r\n\r\n— Ч-что, я же в-вызывал д-демона с-среднего класса. Т-ты не похож н-на н-него.\r\n\r\n— Конечно, мне было интересно за тобой наблюдать, так что я пришёл лично.\r\n\r\n— Хахаха, мне типо повезло? — нервно проговорил маг.\r\n\r\n— Хах, ну можно и так сказать. И что же у тебя случилось, раз ты решил прибегнуть к призыву сразу среднего демона, который тебе даже не по зубам? Так и быть, исполню твоё желание вместо него.\r\n\r\n— Я-я, мне н-нужны деньги н-на опер-рацию сестре. Она тяжело больна, а с-сегодня ещё и с-ситуация ус-сложнилась, так ч-что деньги н-нужны с-срочно.\r\n- Ну чтож хорошо, я помогу тебе, но ты наверное прекрасно знаешь что взамен ты должен мне отдать свою душу. Ты согласен?\r\n- Д-да.\r\n- Отлично. Сейчас на твой счёт была переведена нужная сумма, можешь проверить, а операция назначена на послезавтра. Я приду за тобой после неё. Ты меня понял?\r\n- Д-да, конечно.\r\n- Тогда прощай, ещё увидимся.- и ухмыляяся демон испарился. Парень же остался в смешенных чувствах. С одной стороны он поможет сестре, но с другой умрёт. Он не зал что делать и решил просто смериться, ведь уже ничего изменить не мог. Он сам избрал этот путь, так что винить тут некого. Завтра он пойдёт к сестре и морально подготовит её к грядушей операции, а себя на смерть.','/static/images/placeholder.jpg',0,'2026-03-15 21:54:37'),(11,'Demo',8,'# Заголовок\r\n## Подзаголовок\r\n### Раздел\r\n* текст\r\n> текст\r\nтекст\r\n---\r\n1. текст\r\nтекст','/static/uploads/fanfics/cover_11.png',0,'2026-03-15 21:58:27'),(12,'Чай для двоих.. 💤 (4 часть)',13,'МЫ РЕЗКО ОСУЖДАЕМ И НИ В КОЕМ СЛУЧАЕ НЕ ПОДДЕРЖИВАЕМ: НАЦИЗМ, ФАШИЗМ, РАСИЗМ, КСЕНОФОБИЮ, АНТИСЕМИТИЗМ, ИСЛАМОФОБИЮ, ГОМОФОБИЮ, ТРАНСФОБИЮ, СЕКСИЗМ, ЭЙДЖИЗМ, ДИСКРИМИНАЦИЮ ПО ИНВАЛИДНОСТИ, РЕЛИГИОЗНУЮ НЕТЕРПИМОСТЬ, ЭКСТРЕМИЗМ, ШОВИНИЗМ, ФИЗИЧЕСКОЕ И ПСИХОЛОГИЧЕСКОЕ НАСИЛИЕ, ДОМАШНЕЕ НАСИЛИЕ, ГЕНОЦИД, ТЕРРОРИЗМ, ПЫТКИ, ЖЕСТОКОЕ ОБРАЩЕНИЕ С ЖИВОТНЫМИ, КВАДРОБИНГ, ХОБИХОРСНИГ, ДЕТОУБИЙСТВО, СЕКСУАЛЬНОЕ НАСИЛИЕ, ТОРГОВЛЮ ЛЮДЬМИ, РАБСТВО, КИБЕРБУЛЛИНГ, ТРАВЛЮ (БУЛЛИНГ), СЕЛФХАРМ, ПРОПАГАНДУ СУИЦИДА, КОРРУПЦИЮ, ВАНДАЛИЗМ, ВЫМОГАТЕЛЬСТВО, МОШЕННИЧЕСТВО, КРАЖУ, ГРАБЕЖ, РАЗБОЙ, УБИЙСТВА, НАРКОТОРГОВЛЮ, НЕЗАКОННЫЙ ОБОРОТ ОРУЖИЯ, ПИРАТСТВО, ПРОПАГАНДУ ПРЕСТУПНОГО ОБРАЗА ЖИЗНИ, НАРКОМАНИЮ, АЛКОГОЛИЗМ, ТОКСИКОМАНИЮ, ИГРОВУЮ ЗАВИСИМОСТЬ, ДЕСТРУКТИВНЫЕ КУЛЬТЫ, ОПАСНЫЕ ЧЕЛЛЕНДЖИ, ФЕЙКОВЫЕ НОВОСТИ, ТЕОРИИ ЗАГОВОРА, ЛЖЕНАУКУ, МАНИПУЛЯЦИИ СОЗНАНИЕМ, ГАЗЛАЙТИНГ, ЭКОЛОГИЧЕСКИЙ ВАНДАЛИЗМ, ПРОПАГАНДУ ВОЙН, ВОЕННЫЕ ПРЕСТУПЛЕНИЯ, НАРУШЕНИЕ ПРИВАТНОСТИ, КЛЕВЕТУ, ХАРАССМЕНТ И ЛЮБЫЕ ДРУГИЕ ФОРМЫ НАСИЛИЯ, ДИСКРИМИНАЦИИ ИЛИ НЕЗАКОННОЙ ДЕЯТЕЛЬНОСТИ.\r\n\r\n⚠️ здесь не будет никаких постельных сцен, поцелуев, и любых проявлений гейства со стороны персонажей, если вы пришли за этим, то разочарую, всё неправда, я не в коем случае не пытался никого оскорбить ⚠️\r\n\r\nЭто альтернативная вселенная фанфика *дружба это чудо*, где андрей не опоздал, а пришёл вовремя.\r\n\r\nchapter 4 /\r\n\r\n*Уже оплатив покупки, Андрей вышел из магазина, заказав такси до дома.*\r\n\r\nА - Ммм… Надо глянуть, где этот таксист… И вообще, какая машина.\r\n\r\n*Открыв приложение Яндекс, он проверил номер машины и заметил, что она уже стоит рядом. Подойдя и открыв дверь, он сел на переднее сиденье, держа пакет с продуктами в руках.*\r\n\r\nА - Здравст-…\r\n\r\n*Не успев договорить, Андрей посмотрел на таксиста… который оказался его одноклассником?..*\r\n\r\nА - Ваня?\r\n\r\n*Ваня аристократично посмеялся в ответ, поправив свою кепку, и спокойным голосом с лёгкой насмешкой ответил:*\r\n\r\nИ - Привет, коротышка. Устал, наверное, ходить?\r\n\r\nА - …\r\n\r\n|Вернёмся к нашей святой тройке гее...героев| \r\n\r\n*Пока Андрей был в магазине, они успели сбежать, прихватив с собой Ярослава.*\r\n\r\nП - …Не, я больше не могу его на руках нести…\r\n\r\n*С усталостью сказал Павел, явно оказавшись слабее, чем думал.*\r\n\r\nП - Я помню, вроде у них тут тачка была какая-то.\r\n\r\nС - Хуйня идея.\r\n\r\nП - Иди нахуй. Идеи лучше есть?\r\n\r\nС - Вообще-то есть.\r\n\r\n*Павел с недоверием посмотрел на Семёна, но был заинтригован.*\r\n\r\nС - Понимаешь, когда Андрей только пришёл за мной, я сразу заподозрил что-то неладное. Ведь я сам тот ещё кукловод-манипулятор. Поэтому я позвонил сам себе со второго телефона, дабы уйти, не вызвав подозрений, после чего набрал-..\r\n\r\n*Его перебивает громкий звук вертолётных лопастей. Подняв головы, они замечают Bell 407, стремительно заходящий на посадку.*\r\n\r\n*Управляла вертолётом… Аня? А рядом с ней на переднем пассажирском сиденье сидела… Аня постарше.*\r\n\r\nП - Это что за армянский вертолёт…\r\n\r\nА(В) - …\r\n\r\nАгрессивное молчание.\r\n\r\nА(С) - Ну раз вам помощь не нужна…\r\n\r\nС - Нужна. Очень нужна, не слушайте этого одноклеточного.\r\n\r\nП - Ахуел?\r\n\r\n*Семён лишь ткнул его локтём в живот, от чего Паша скрутился.*\r\n\r\nП - И всё же идея с машиной была лучше…\r\n\r\nА(В) - Садись уже, неблагодарный.\r\n\r\nС - Да, садись уже.\r\n\r\n*Семён слегка толкнул Пашу вперёд к вертолёту.*\r\n\r\nС - Рад, что вы прилетели. Честно говоря, не ожидал.\r\n\r\nА(С) - Должен будешь…\r\n\r\nА(В) - Натурой заплатишь. Денёчек поработаешь - и мы в расчёте.\r\n\r\nП - Хахаха… влип ты, лох.\r\n\r\nА(С) - А ты чего смеёшься? Ты тоже нам должен.\r\n\r\nА(В) - Ты будешь подороже работать. Формы у тебя хорошие.\r\n \r\n*спустя час* \r\n\r\n*Вертолёт с неприятным скрипом приземлился прямо во дворе, подняв пыль и листья.*\r\n\r\nС - Опасно… Вдруг кто полицию вызовет?\r\n\r\nП - Да расслабься ты, тут и не такое видели.\r\n\r\n*Лопасти постепенно замедляются, но шум всё ещё стоит сильный.*\r\n\r\nА(В) -  Всё, выгружайтесь. Цирк приехал.\r\n\r\nП - Сама ты цирк.\r\n\r\nА(С) - Щас обратно в подвал поедешь, клоун.\r\n\r\nП - Всё, молчу.\r\n\r\n*Паша открывает дверь и пытается вытащить Ярослава.*\r\n\r\nП - …Он что, бетонный?\r\n\r\nС - Это ты просто слабый.\r\n\r\nП - Иди сюда тогда, сильный, помогай.\r\n\r\n*Семён берёт Ярика под руки, и вместе они кое-как вытаскивают его из вертолёта.*\r\n\r\n*Ярик все так же в отключке, но выглядит так, будто ему вообще нормально.*\r\n\r\nП - Он точно жив?\r\n\r\nС - Не знаю. Но если нет - это плохо.\r\n\r\nП - Отличный настрой, мне нравится.\r\n\r\n*Они тащат Ярика к подъезду.*\r\n\r\nП - Я щас его уроню, клянусь.\r\n\r\nС - Не урони, он нам ещё нужен.\r\n\r\nП - Да кому он нахуй нужен вообще?\r\n\r\nС - Нам. Во-первых, пленник, во-вторых, помощник, а в-третьих, он знает об Андрее больше чем мы когда либо знали\r\n\r\nП - …Ладно, аргумент.\r\n\r\n*Подойдя к подъезду:*\r\n\r\nП - Сём, ключи достань.\r\n\r\nС - У меня руки заняты вообще-то.\r\n\r\nП - А у меня, блять, нет?\r\n\r\n*Пауза.*\r\n\r\nП - Ладно.\r\n\r\n*Он отпускает Ярика.*\r\n\r\n*Глухой звук удара о землю.*\r\n\r\nС - …\r\n\r\nП - …\r\n\r\nС - Ты его уронил.\r\n\r\nП - Он сам упал.\r\n\r\n*Через пару секунд они всё же заходят в подъезд и начинают подниматься по лестнице.*\r\n\r\nП - Почему мы не поднялись на лифте?\r\n\r\nС - Потому что лифт не выдержит твою самооценку.\r\n\r\nП - Очень смешно. Давай быстрее, будто твоё эго он выдержит.\r\n\r\n*На третьем этаже Паша уже жалеет о всех своих жизненных выборах.*\r\n\r\nП - Всё, я больше не могу.\r\n\r\nС - Ещё этаж.\r\n\r\nП - Я тут умру.\r\n\r\nС - Отлично, я тогда один донесу.\r\n\r\nП - Не донесёшь.\r\n\r\nС - Не проверяй.\r\n\r\n*Наконец добравшись до квартиры, Паша ногой открывает дверь.*\r\n\r\nП - Всё… я его бросаю.\r\n\r\nС - Подожди-\r\n\r\n*Паша аккуратно (почти) скидывает Ярика на диван.*\r\n\r\nЯ - не просыпается.\r\n\r\nП - Всё, живой.\r\n\r\nС - Это не показатель.\r\n\r\nП - Мне похуй, я устал.\r\n\r\n*Паша сразу падает за комп, как будто ничего не произошло.*\r\n\r\nП - Всё, я разрабатываю план мести.\r\n\r\nС - Ты пять минут назад умирал на лестнице.\r\n\r\nП - Это не мешает мне быть гением.\r\n\r\n*Паша сел за комп, чтобы «придумать план, как отомстить Андрею». За ним в комнату зашёл Семён, уложил Ярика на диван и спросил:*\r\n\r\nС - А мне что делать?\r\n\r\nП - За Яриком следи. Справишься?\r\n\r\nС - Вполне.\r\n\r\n|Обратно к Андрею|\r\n\r\n*Довёз ли его Иван-таксист-британец, что так любит аристократично смеяться?*\r\n\r\nА - …Ладно, спасибо, до свидания.\r\n\r\nИ - Давай, коротышка. В следующий раз будь аккуратнее, а то без такси своими ножками не дошёл бы — там в магазине и остался бы, пока тебя Ирина Васильевна не нашла.\r\n\r\nА - Ирина Васильевна?.. Ладно…\r\n\r\n*Ваня уехал, а Андрей зашёл в дом. Первое, что он увидел - спящий на полу Гоша.*\r\n\r\nА - Аэ… Гоша…\r\n\r\n*Слегка ткнул ногой.*\r\n\r\nА - ГОША! Подъём, я тебе не за сон плачу!\r\n\r\nГ - Аао… что… а, Андроид, ты… чего орёшь?\r\n\r\nА - Мы же договаривались, что ты перестанешь спать на полу… да и на работе в принципе.\r\n\r\nГ - Простите, насяльника, больше так не пофтариться.\r\n\r\n*Андрей устало выдохнул и прошёл внутрь дома, заметив, что дверь подвала открыта. Он испугался и быстро спустился вниз, обнаружив, что его рабов нет, как и Ярика.*\r\n\r\nГ - Неловко вышло… мм… мне же заплатят хотя бы квасом?\r\n\r\nА - Иди нахуй, ты уволен.\r\n\r\nГ - 🥺😭\r\n\r\nС огромной печалью Гоша ушёл…\r\n\r\nА - Пффф-ф-ф…\r\n\r\n*С усталостью и злостью выдохнул оставшийся один в доме Андрей, нервно постукивая ногой по деревянному полу.*\r\n\r\n…Продолжение следует…','/static/images/placeholder.jpg',0,'2026-04-09 14:51:14'),(13,'Дыхание..',20,'Прежде чем читать, дисклеймер:\r\n​Художественный вымысел: Описанные события и персонажи не являются реальными.\r\n​Уголовная ответственность: Использование ядовитых и сильнодействующих веществ (скополамин и др.), а также причинение вреда здоровью или лишение человека воли — уголовно наказуемые деяния (ст. 111-115, 234 УК РФ).\r\n​Безопасность: Любые попытки повторения подобных экспериментов в реальности ведут к необратимым медицинским последствиям и тюремному сроку.\r\n\r\nКак обычно Дайрен лежал на приятной тёплой кровати, размышляя о своих и чужих поступках тёмной ночью.\r\n- Как же я устал.. Почему жизнь не может быть такой же лёгкой, как в книге. Хотя нет, там книжному Дайрену пришлось ещё хуже, он страдал из-за каждого шага, чтобы добиться красивого финала.\r\nОн вздохнул.\r\n- Как же меня бесит общество: один  странный неуровновешенный, с манией величия, другой вроде умный, но боиться сделать серьёзный, хоть и лёгкий шаг. Хотя я тоже боялся, но ведь решился. Третий вообще, блин, вынес вынос мозгов окружающим в хобби, вот бы его..\r\nВскоре он заснул.\r\n\r\nУтро было совершенно обычным, в школе парень оказался быстро и уже сидел 1 на 1 с Валентиной в тёмном пустом кабинете. Он очень любил находится в этой тишине. В этот раз он пытался досмотреть сериал, когда в кабинет явился Лев\r\n- Всем доброе утро.\r\n- Доброе.. - Вздохнул Дайрен.\r\nС этого момента тишини больше не было, поэтому парень заглянул в телефон и наткнулся на интересную историю о \"дыхании дьявола\".\r\n- Ох, а ведь это идея..\r\nОн подскочил, но был остановлен вопросом:\r\n- Ты куда?\r\n- Мне нужно к химичке.\r\n- Тебе? Зачем? Ты же её недолюбливаешь.\r\n- Буду обожать, если она мне поможет...\r\nНе отвечая на остальные вопросы, он быстро оказался в дверях кабинета химии и постучал. Преподаватель была недовольна его раннему приходу.\r\n- Я сейчас занята, спроси на уроке.\r\n- Всё понимаю, Ирина Владиславовна, но у меня есть интересный проект, связанный с химией.\r\n- Ты разве не инженерный класс?\r\nДайрен вошёл в кабинет.\r\n- Да, у меня скоро конференция, я хочу впечатлить жюри не только тежникой, но знаниями химии. Для этого мне нужно провести небольшой эксперимент с цветком, который входит в проект, и диметилсульфоксидом.\r\n- Ого, зачем же он тебе?\r\n- Хочу проверить его влияние на рост растения.\r\n- Какой-то сомнительный, эксперимент, если честно.\r\n- Ну, я же инженер, куда мне что-то большое?\r\nПарень виновато и слегка соблозняюще улыбнулся.\r\n- Ладно, он у меня есть, посмотри сам, а то мне нужно уроку готовиться.\r\nЭто ему и надо было. Он по-хозяйски зашёл в лабораторную, а со звонком вышел из неё, с диметилсульфоксидом и скополамином. Удивительно, что он смог найти это в школе. Уроки он решил прогулять в пользу идеи. За этот день он достал перчатку и подготовил её к химии, чтобы обезопасить себя. Смешав нужный раствор дома, и намазал его на перчатку, на которую надел пакет, и позвонил Паше.\r\n- Встретимся после уроков, ладно?\r\n- ...\r\n- Супер, до встречи.\r\n\r\nЧерез полчаса Дайрен встретил друга в мастерской, которая была пуста, за исключением них. Он поведал свою задумку и показал перчатку.\r\n- Это интересно, хвх. На ком применим?\r\n- Ты знаешь, кто бы мог быть влюблён в Андрея?\r\n- Ртищева?\r\n- Да.\r\n- А, так это Семён. Он, к тому же, постоянно доминирует над Андреем. - Павел усмехнулся.\r\n- Да, я заметил. Зови его, а как приведёшь, иди с Андрюшей.\r\nПодождав минут пять, Дайрен остался наедине с соломоволосым другом.\r\n- Сёма.. - Он загадочно улыбнулся, говоря завлекающим другом.\r\n- Я сначала хотел подсыпать тебе в чай этот препарат, но решил кое-что тебе предложить.\r\n- Так?\r\n- Хочешь Ртищева?\r\n- В плане?\r\n- Я могу предоставить его тебе абсолютно беспомощным и послушным, к тому же он не вспомнит, что ты с ним сделаешь. - Его улыбка стала шире.\r\n- Звучит заманчиво. - Слегка повысил голос второй в некотором возбуждении.\r\nКогда вошёл Андрей, всё уже было решено. На руке парня уже красовалась перчатка, которой он нежно взял Ртищева за руку.\r\n- Ты что делаешь? - Возразил тот с нервозной улыбкой.\r\n- Сладких снов, Андрюша.\r\nСлой ДМСО сработал мгновенно, протаскивая яд сквозь эпидермис. Спустя пару минут взгляд жертвы стал стеклянным. Мальчик всё еще стоял на ногах, но его воля уже растворилась в скополаминовом тумане. Он не вспомнит ни этого разговора, ни того, что будет делать с Семёном, правда этого не узнаем даже мы, потому что Дайрен оставил трио наедине: они могли делать наедине всё, что хотят, а зная Пашу, Андрей будет долго спрашивать, с помощью кого починили погнутое жало паяльника, и удивляться, почему так болит тело.\r\nНу, ладно, если вы думаете, что соломенный надругался над беспомощным человеком, то вы неправы, Андрей был использован как маникен, а также позже в его телефоне нашлось множество разнообразных фоток, а что до паяльника.. лучше спросить Пашу, тут я не ручаюсь..\r\n\r\nЕсли вам понравилось - хорошо, нет - ладно. Если у вас будут ещё идеи, про что написать,  смело говорите)','/static/images/placeholder.jpg',0,'2026-04-21 20:09:48'),(14,'Шёпот..',20,'​ДИСКЛЕЙМЕР\r\n​Художественный вымысел: Описанные события, персонажи и «вторые личности» не являются реальными.\r\n​Уголовная ответственность: Использование ядов (ст. 234 УК РФ), нападение (ст. 111–116 УК РФ) и подделка документов (ст. 327 УК РФ) — тяжкие преступления.\r\n​Психическое здоровье: Изображение галлюцинаций и расслоения личности носит драматический характер и не является пособием по психологии.\r\n​Опасно: Повторение действий героев в реальности ведет к тюремному сроку и смертельной опасности для здоровья.\r\n\r\nС данного фф будет формат повестования \"от первого лица\". Приятного чтения!\r\n\r\n- Дайрен. - Разбудил от оцепенения голос учителя химии. На этом чудесном уроке я зачастую впадал в дремоту.\r\n- Здесь. - Пришлось отозваться.\r\n- Задержитесь после звонка.\r\nВскоре, минут через пять, он и прозвенел. Я неспешно собрал вещи и подошёл к Ирине Владиславовне. Когда народ рассасался, она начала говорить.\r\n- Во-первых, ты не вернул мне то, что взял.\r\n- Запамятовал, простите.\r\n- А во-вторых, зачем ты взял скополамин?\r\n- М?\r\n- После твоего прихода он исчез.\r\nКажется, про это забыл, я ведь даже не знаю, как выкручиваться.. Надо было догадаться, что \"дыхание\" под жётским контролем. Тц, что же делать.. идиот..\r\n- Да? - Скрывать смысла нет. - Да, я его взял.\r\n- Зачем.\r\n- О, сейчас покажу.\r\nУлыбнувшись, я полез в рюкзак, где незаметно надел перчатку и освободил её от пакета.\r\n- Что ты там ищешь?\r\nРезко я набросился на неё и сжал в руке её руку.\r\n- Что ты делаешь?\r\n- Тс, не дергайтесь.\r\nОна пыталась вырваться, что начало получаться ввиду моей слабости, а ещё забыл про то, что яд действует не сразу.\r\n- Ах ты! - Она со всей силы дала пощёчину, заставив замереть на пару секунд. Времени было достаточно, чтобы ей выбраться, но и скополамин уже успел в достаточных дозах проникнуть через кожу.\r\n- Ты совсем охамел?!\r\n- Простите, не понимаю, что на меня нашло. - Виновато опустил глаза, смотря на перчатку.\r\nБлин, совсем уже сухая.\r\n- Где то, что ты у меня взял?!\r\n- Что я у вас взял?\r\n- Ты знаешь!\r\n- Что?\r\nОна ударила кулаком по столу и встала. Я на неё не смотрел.\r\n- Я на тебя докладную напишу о воровстве!\r\nОна орала и орала, но становилась тише, речь смешалась в бред, и она обмякла. Подняв голову, я сел за её кресло и составил кое-какой документ, который распечатал и положил перед учителем.\r\n- Подпишите здесь. - Я вложил ручке ей в руку и показал пальцем.\r\nИрина долго смотрела пустыми, расширенными зрачками на листок бумаги, но мышечная память сработала почти безошибочно, она медленно поставила свою закарючка, та получилось похожей, но немного \"пьяной\".\r\n- То-то же. Садитесь.\r\nПока я делал копии, она села в кресло, послышалось предупреждение о начале урока.\r\n- Боже.\r\nПришлось запереть кабинет. Ключи я нашёл на столе. Спрятав копии и оригинал, вернул все вещества на место, предварительно восстановив покрытие перчатки, которую потом спрятал в пакет  и рюкзак. К счастью, у химички не предвкщалось урока, поэтому я дождался её пробуждения.\r\n- Что произошло?.. На чём мы остановились? - Она потерянным взглядом смотрела на него.\r\n- А, я вернул вам реагенты, вы меня похвалили за моё рвение к изучению химии и слегка задремали.\r\n- Да?.. Ладно, иди.\r\n- Хорошего дня!\r\nДаже не потребовались документы. Вхух, пронесло.. Так ладно, прошло минут тридцать от урока. Задумавшись, на автомате я пришёл в, как казалось, знакомое место, а потом осознал, что иду по старой лестнице, которая, видимо не учавствовала в ремонте школы спустившись ещё ниже, открылось новое место: тёмный подвал, видимо бомбоубежище. Никогда здесь не был. В кромешной тьме получилось разглядеть пару санузлов и немаленькое количество комнат. Неожиданно позади погас свет, шедший снаружи, а темнота сгустилась, это заставило меня обернутся.\r\n- Ха, я дождался идельного момента. - Послышался шёпот.\r\nСнова обернулся. Ничего. А тем временем шёпот продолжил.\r\n- Как же ты налажал. Посмотреть камеры, всё будет понятно. Да и при рассмотрении данной подписи профессионалами вскроются моменты.\r\nЯ был на взводе, нервы расшалились.\r\n- Покажись!\r\nРезко дёрнули переключатель, вокруг оказалась бесконечная белая комната. По центру сидел полностью закутанный в чёрное человек: чёрные ботинки, штаны, кофта, перчатки, маска и капюшон на голове. Человек в чёрной маске. Оказался я почему-то на стуле напротив.\r\n- Ч-что? Только что был подвал.. где мы?..\r\n- М, в твоей голове. - Его голос был спокоен и холоден.\r\n- Хах, смешно.. Так где мы?\r\n- В твоей.. - Он сделал небольшую паузу. - ... голове\r\nЯ попытался встать, но тело не послушалось, зато встал он.\r\n- Можешь называть меня Ч. Я твой осколок личности, только благодаря мне ты ещё нормальный.\r\n- Чел, это всё звучит, как полнейший бред. Ты просто взял и появился, только сделал я шаг в подвал? Хах, смешно. Нету чего креативней?\r\n- Креативней? - Он сказал это со злостью в голосе. Неожиданно я оказался повисшем на краю школьной крыши, и только рука Ч, державшая за шкирку спасала от падения.\r\n- Достаточно креативно?!\r\n- Нет, стой!\r\nОн разжал руку.\r\n- Этим для тебя всё закончится!\r\nГолова ударилась о холодный подвальный пол, глаза не могли привыкнуть к темноте, сердце бешенно билось.\r\n- Я просто надышался здесь чем-то..\r\n- Ты так давно терпел, Дайри.. - Продолжал голос из тьмы. - Не хочется ли тебе отомстить?\r\n- Заткнись.. - Голова пульсировала, холодный пол не спасал.\r\n- А зачем тебе тогда эта перчатка?\r\nЗнакомая перчатка схватила за шею. Я нащупал руку, схватил, попытался оторвать но он был сильнее...\r\nОткрыв глаза, я сидел в тёмном кабинете информатики, напротив Валентины Леонидовны.\r\n- Ой, я кажется задремал..\r\n- Не выспался сегодня? - Поинтересовалась собеседница.\r\n- Ох, видимо.\r\nЯ увидел человека. Он направил оружие на преподавателя, не глядя. Чёрная маска стояла сбоку.\r\n- Нет, стой!\r\n- Дайрен, ты чего? - От неожиданности она вздрогнула.\r\n- Только ты меня видишь, Змейка, I\'m only in your mind!\r\nЧ направил пистолет на меня, спустил курок и.. я врезался лицом в холодную стену и снова оказался на подвальном полу.\r\n- Хахах, как же мне это нравится! - Вскричал шёпот. Он раздавался эхом в голове, отскакивал от стенок сознания.\r\n- Пожалуйста, хватит...\r\n- Да ладно, какой ты скучный! - На грудь наступила тяжёлая нога. - Согласен на мою помощь?\r\n- Да-да-да, только отпусти..\r\n- Ладно, отдохни пока.\r\nБоль отступила. Сознание помутнело. Вздох и.. уснул.','/static/images/placeholder.jpg',0,'2026-04-24 22:33:53'),(15,'Хдрян офчцтн шдсшмо',23,'Щр... Ёя щтципм чёмзица шдсшмо?\r\nСиц, лзиха ижт си ечзиц. Лзиха ечзиц ьмшф м рдпвхисаодг мжфд :)\r\nД рткиц, м си рдписаодг.\r\nЦдо ыцт жтцтёациха о цтрч, ыцт ёя ечзици тердсчця м чзмёпися.\r\nД опвы о фдлждзои — бцт 4.\r\nД цдоки хпизчвэдг утзходлод ечзиц цдотёд:\r\n\r\nУпчц ьиусчп: «хрТцфм, одо \r\nЁхищ хиныдх г уфтёизч.\r\nИхца Птёомн упдс, м ёя ё Мжфи,\r\nХодкиьА — м очь чки ё фчои.\r\nПмьа Тзмс рмж — ст Щмцфян щтз. М ё одуодс мщ лдёизйц, ёиха тердсчцян сдфтз».','/static/images/placeholder.jpg',0,'2026-04-26 20:15:10');
